        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90020004-0000-4000-8000-000000000001', 'Which of the following is an irrational number?', '{"A":"√4","B":"√(9/16)","C":"√7","D":"0.375"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '√7 is a non-terminating, non-recurring decimal and cannot be expressed as p/q where p, q are integers and q ≠ 0.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000002', 'The decimal expansion of (22/7) is:', '{"A":"Terminating","B":"Non-terminating recurring","C":"Non-terminating non-recurring","D":"Non-existent"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '22/7 is a rational number. Decimal expansions of rational numbers are either terminating or non-terminating recurring (repeating block of 6 digits: 3.142857...).', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000003', 'The degree of the zero polynomial is:', '{"A":"0","B":"1","C":"Any natural number","D":"Not defined"}'::jsonb, 'D', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By standard algebraic definition, the degree of the zero polynomial p(x) = 0 is undefined.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000004', 'If (x - 1) is a factor of polynomial p(x) = kx² - 3x + k, what is the value of k?', '{"A":"3/2","B":"-3/2","C":"3","D":"-3"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By Factor Theorem, p(1) = 0 -> k(1)² - 3(1) + k = 0 -> 2k - 3 = 0 -> k = 3/2.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000005', 'Point (-3, -5) lies in which quadrant of the Cartesian coordinate plane?', '{"A":"Quadrant I","B":"Quadrant II","C":"Quadrant III","D":"Quadrant IV"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Coordinate Geometry', 1, NULL, NULL, NULL, 'In Quadrant III, both the x-coordinate (abscissa) and y-coordinate (ordinate) are strictly negative.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000006', 'The linear equation 2x + 3y = 6 cuts the y-axis at which point?', '{"A":"(3, 0)","B":"(0, 2)","C":"(2, 0)","D":"(0, 3)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Equations in Two Variables', 1, NULL, NULL, NULL, 'On the y-axis, x = 0. Substituting: 2(0) + 3y = 6 -> 3y = 6 -> y = 2. So the coordinates are (0, 2).', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000007', 'A linear equation in two variables ax + by + c = 0 has how many real solutions?', '{"A":"A unique solution","B":"Only two solutions","C":"Infinitely many solutions","D":"No solution"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Linear Equations in Two Variables', 1, NULL, NULL, NULL, 'Every point lying on the straight line represented by the equation is a solution; thus it possesses infinitely many solutions.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000008', 'According to Euclid''s Axiom 1, things which are equal to the same thing are:', '{"A":"Double of each other","B":"Half of each other","C":"Equal to one another","D":"Perpendicular"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Introduction to Euclid''s Geometry', 1, NULL, NULL, NULL, 'Euclid''s First Axiom: ''Things which are equal to the same thing are also equal to one another.''', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000009', 'If two complementary angles are in the ratio 2 : 3, what is the measure of the smaller angle?', '{"A":"36°","B":"54°","C":"30°","D":"45°"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Lines and Angles', 1, NULL, NULL, NULL, 'Complementary angles sum to 90°. Let angles be 2x and 3x. 2x + 3x = 90° -> 5x = 90° -> x = 18°. Smaller angle = 2 * 18° = 36°.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000a', 'In triangle ABC, if AB = AC and angle B = 50°, then angle A is:', '{"A":"50°","B":"80°","C":"100°","D":"65°"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Triangles', 1, NULL, NULL, NULL, 'Since AB = AC, ∠C = ∠B = 50° (angles opposite to equal sides are equal). By angle sum property: ∠A = 180° - (50° + 50°) = 80°.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000b', 'Which of the following is NOT a criterion for congruence of triangles?', '{"A":"SAS","B":"ASA","C":"SSA","D":"SSS"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Triangles', 1, NULL, NULL, NULL, 'SSA (Side-Side-Angle) is not a valid congruence condition because two non-congruent triangles can share two sides and a non-included angle.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000c', 'The diagonals of a rhombus have lengths 16 cm and 12 cm. What is the length of each side of the rhombus?', '{"A":"10 cm","B":"14 cm","C":"20 cm","D":"8 cm"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Quadrilaterals', 1, NULL, NULL, NULL, 'Diagonals of a rhombus bisect each other at right angles. In right triangle formed by half-diagonals (8 cm and 6 cm): side² = 8² + 6² = 64 + 36 = 100 -> side = 10 cm.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000d', 'The angle subtended by a semicircle at any point on the circle is:', '{"A":"45°","B":"60°","C":"90°","D":"180°"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Circles', 1, NULL, NULL, NULL, 'The angle subtended by a diameter or semicircle at any point on the circumference is always a right angle (90°).', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000e', 'If an equilateral triangle has a perimeter of 60 cm, its area using Heron''s formula is:', '{"A":"100√3 cm²","B":"150√3 cm²","C":"200√3 cm²","D":"300 cm²"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Heron''s Formula', 1, NULL, NULL, NULL, 'Side a = 60 / 3 = 20 cm. Area of equilateral triangle = (√3 / 4) * a² = (√3 / 4) * 400 = 100√3 cm².', 'MEDIUM', true),
        ('90020004-0000-4000-8000-00000000000f', 'If the radius of a sphere is doubled, its surface area becomes:', '{"A":"2 times","B":"4 times","C":"8 times","D":"16 times"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Surface Areas and Volumes', 1, NULL, NULL, NULL, 'Surface area S = 4πr². When r'' = 2r, S'' = 4π(2r)² = 4 * (4πr²) = 4S.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000010', 'The total surface area of a cone of radius r and slant height l is given by:', '{"A":"πrl","B":"πr(l + r)","C":"2πr(l + r)","D":"πr²l"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Surface Areas and Volumes', 1, NULL, NULL, NULL, 'Total Surface Area = Curved Surface Area + Base Area = πrl + πr² = πr(l + r).', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000011', 'The mean of five numbers is 30. If one number is excluded, their mean becomes 28. The excluded number is:', '{"A":"36","B":"38","C":"40","D":"42"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Statistics', 1, NULL, NULL, NULL, 'Sum of 5 numbers = 5 * 30 = 150. Sum of remaining 4 numbers = 4 * 28 = 112. Excluded number = 150 - 112 = 38.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000012', 'In a frequency distribution, the class mark of the class 130 - 150 is:', '{"A":"135","B":"140","C":"145","D":"20"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Statistics', 1, NULL, NULL, NULL, 'Class mark = (Lower limit + Upper limit) / 2 = (130 + 150) / 2 = 140.', 'MEDIUM', true),
        ('90020004-0000-4000-8000-000000000013', 'Assertion (A): The polynomial p(x) = 3x² + 5x - 2 is a quadratic polynomial.
