        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90020016-0000-4000-8000-000000000001', 'Which of the following is an irrational number?', '{"A":"√4","B":"√(9/16)","C":"√7","D":"0.375"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '√7 is a non-terminating, non-recurring decimal and cannot be expressed as p/q where p, q are integers and q ≠ 0.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000002', 'The decimal expansion of (22/7) is:', '{"A":"Terminating","B":"Non-terminating recurring","C":"Non-terminating non-recurring","D":"Non-existent"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '22/7 is a rational number. Decimal expansions of rational numbers are either terminating or non-terminating recurring (repeating block of 6 digits: 3.142857...).', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000003', 'The degree of the zero polynomial is:', '{"A":"0","B":"1","C":"Any natural number","D":"Not defined"}'::jsonb, 'D', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By standard algebraic definition, the degree of the zero polynomial p(x) = 0 is undefined.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000004', 'If (x - 1) is a factor of polynomial p(x) = kx² - 3x + k, what is the value of k?', '{"A":"3/2","B":"-3/2","C":"3","D":"-3"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By Factor Theorem, p(1) = 0 -> k(1)² - 3(1) + k = 0 -> 2k - 3 = 0 -> k = 3/2.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000005', 'Point (-3, -5) lies in which quadrant of the Cartesian coordinate plane?', '{"A":"Quadrant I","B":"Quadrant II","C":"Quadrant III","D":"Quadrant IV"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Coordinate Geometry', 1, NULL, NULL, NULL, 'In Quadrant III, both the x-coordinate (abscissa) and y-coordinate (ordinate) are strictly negative.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000006', 'The linear equation 2x + 3y = 6 cuts the y-axis at which point?', '{"A":"(3, 0)","B":"(0, 2)","C":"(2, 0)","D":"(0, 3)"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Linear Equations in Two Variables', 1, NULL, NULL, NULL, 'On the y-axis, x = 0. Substituting: 2(0) + 3y = 6 -> 3y = 6 -> y = 2. So the coordinates are (0, 2).', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000007', 'A linear equation in two variables ax + by + c = 0 has how many real solutions?', '{"A":"A unique solution","B":"Only two solutions","C":"Infinitely many solutions","D":"No solution"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Linear Equations in Two Variables', 1, NULL, NULL, NULL, 'Every point lying on the straight line represented by the equation is a solution; thus it possesses infinitely many solutions.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000008', 'According to Euclid''s Axiom 1, things which are equal to the same thing are:', '{"A":"Double of each other","B":"Half of each other","C":"Equal to one another","D":"Perpendicular"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Introduction to Euclid''s Geometry', 1, NULL, NULL, NULL, 'Euclid''s First Axiom: ''Things which are equal to the same thing are also equal to one another.''', 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000009', 'If two complementary angles are in the ratio 2 : 3, what is the measure of the smaller angle?', '{"A":"36°","B":"54°","C":"30°","D":"45°"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Lines and Angles', 1, NULL, NULL, NULL, 'Complementary angles sum to 90°. Let angles be 2x and 3x. 2x + 3x = 90° -> 5x = 90° -> x = 18°. Smaller angle = 2 * 18° = 36°.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000a', 'In triangle ABC, if AB = AC and angle B = 50°, then angle A is:', '{"A":"50°","B":"80°","C":"100°","D":"65°"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Triangles', 1, NULL, NULL, NULL, 'Since AB = AC, ∠C = ∠B = 50° (angles opposite to equal sides are equal). By angle sum property: ∠A = 180° - (50° + 50°) = 80°.', 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000b', 'Express 0.2353535... (i.e. 0.235 with bar on 35) in the p/q form, where p and q are integers and q ≠ 0.', NULL, NULL, 'VSA', 'Mathematics', 'Number Systems', 2, 'Let x = 0.2353535... Multiplying by 10: 10x = 2.353535... (Eq 1). Multiplying by 1000: 1000x = 235.353535... (Eq 2). Subtracting Eq 1 from Eq 2: 990x = 233 -> x = 233 / 990.', '1 Mark for setting up equations with appropriate multipliers 10 and 1000; 1 Mark for subtraction and final simplified fraction 233/990', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000c', 'Find the value of the polynomial p(y) = 2 + y + 2y² - y³ at: (i) y = 0, (ii) y = 2.', NULL, NULL, 'VSA', 'Mathematics', 'Polynomials', 2, '(i) p(0) = 2 + 0 + 2(0)² - (0)³ = 2. (ii) p(2) = 2 + 2 + 2(2)² - (2)³ = 4 + 8 - 8 = 4.', '1 Mark for calculating p(0) = 2; 1 Mark for calculating p(2) = 4', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000d', 'In which quadrants or on which axes do the following points lie: A(0, -4), B(-2, 3), C(5, 0), D(4, -3)?', NULL, NULL, 'VSA', 'Mathematics', 'Coordinate Geometry', 2, 'A(0, -4) lies on the negative y-axis. B(-2, 3) lies in Quadrant II. C(5, 0) lies on the positive x-axis. D(4, -3) lies in Quadrant IV.', '0.5 Mark for each correctly identified quadrant/axis location (total 2 Marks)', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000e', 'Rationalise the denominator of: 1 / (7 + 3√2).', NULL, NULL, 'SA', 'Mathematics', 'Number Systems', 3, 'Multiplying numerator and denominator by conjugate (7 - 3√2): [1 * (7 - 3√2)] / [(7 + 3√2)(7 - 3√2)] = (7 - 3√2) / [7² - (3√2)²] = (7 - 3√2) / [49 - (9 * 2)] = (7 - 3√2) / (49 - 18) = (7 - 3√2) / 31.', '1 Mark for identifying conjugate; 1 Mark for denominator difference of squares (49 - 18); 1 Mark for final rationalized fraction', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-00000000000f', 'Factorise completely using the identity: 27x³ + y³ + z³ - 9xyz.', NULL, NULL, 'SA', 'Mathematics', 'Polynomials', 3, 'Rewrite as: (3x)³ + y³ + z³ - 3(3x)(y)(z). Using identity a³ + b³ + c³ - 3abc = (a + b + c)(a² + b² + c² - ab - bc - ca) where a = 3x, b = y, c = z: = (3x + y + z)[(3x)² + y² + z² - (3x)(y) - y(z) - z(3x)] = (3x + y + z)(9x² + y² + z² - 3xy - yz - 3zx).', '1 Mark for recognizing cubic identity; 1 Mark for substitution of terms; 1 Mark for expanded second polynomial factor', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000010', 'Draw the graph of the linear equation 2x + y = 6. Find the coordinates of the points where the line crosses the coordinate axes.', NULL, NULL, 'SA', 'Mathematics', 'Linear Equations in Two Variables', 3, 'Find solutions: When x = 0, y = 6 -> (0, 6). When y = 0, 2x = 6 -> x = 3 -> (3, 0). When x = 1, y = 4 -> (1, 4). Plotting these points on graph and drawing a line through them gives the graph. The line crosses the x-axis at (3, 0) and the y-axis at (0, 6).', '1 Mark for finding table of three points; 1 Mark for plotting straight line graph; 1 Mark for identifying intercepts (3, 0) and (0, 6)', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000011', 'A dome of a building is in the form of a hemisphere. From inside, it was whitewashed at the cost of ₹ 498.96. If the cost of whitewashing is ₹ 2.00 per square meter, find: (i) the inside surface area of the dome, (ii) the volume of the air inside the dome. (Use π = 22/7)', NULL, NULL, 'LA', 'Mathematics', 'Surface Areas and Volumes', 5, '(i) Cost = Rate * Area -> Inside surface area = Total Cost / Rate = 498.96 / 2 = 249.48 m². (ii) For hemisphere, inside CSA = 2πr² = 249.48. 2 * (22/7) * r² = 249.48 -> r² = (249.48 * 7) / 44 = 1746.36 / 44 = 39.69 -> r = √39.69 = 6.3 meters. Volume of air inside dome = (2/3)πr³ = (2/3) * (22/7) * (6.3)³ = (2/3) * (22/7) * 250.047 = (44/21) * 250.047 = 523.908 m³.', '2 Marks for finding inside surface area 249.48 m²; 1.5 Marks for calculating radius r = 6.3 m; 1.5 Marks for calculating volume 523.908 m³', NULL, NULL, 'MEDIUM', true),
        ('90020016-0000-4000-8000-000000000012', 'Based on the Cartesian layout, answer: (i) In which quadrant does Hurdle A lie, and what is its perpendicular distance from the x-axis? (ii) What geometric shape is formed by joining the points A, B, C, and D in order? (iii) Find the perimeter of the figure ABCD.', NULL, NULL, 'CASE', 'Mathematics', 'Coordinate Geometry', 4, '(i) Hurdle A(4, 3) lies in Quadrant I. Its perpendicular distance from the x-axis is equal to the absolute ordinate |y| = 3 units. (ii) AB = 3 - (-3) = 6 units (vertical). BC = 4 - (-4) = 8 units (horizontal). CD = 6 units. DA = 8 units. All interior angles are 90°. Hence, ABCD forms a Rectangle. (iii) Perimeter = 2 * (length + breadth) = 2 * (8 + 6) = 2 * 14 = 28 units.', '1 Mark for Quadrant I and distance 3; 1.5 Marks for proving Rectangle; 1.5 Marks for calculating perimeter 28 units', 'Students of Class 9 organized a sports day race. The track is marked on a Cartesian grid where the starting point is at origin O(0, 0). Hurdle A is placed at point (4, 3), water booth B is at (4, -3), medical station C is at (-4, -3), and finish flag D is at (-4, 3).', NULL, 'MEDIUM', true)
