        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('9002001a-0000-4000-8000-000000000001', 'Which of the following is an irrational number?', '{"A":"√4","B":"√(9/16)","C":"√7","D":"0.375"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '√7 is a non-terminating, non-recurring decimal and cannot be expressed as p/q where p, q are integers and q ≠ 0.', 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000002', 'The decimal expansion of (22/7) is:', '{"A":"Terminating","B":"Non-terminating recurring","C":"Non-terminating non-recurring","D":"Non-existent"}'::jsonb, 'B', 'MCQ', 'Mathematics', 'Number Systems', 1, NULL, NULL, NULL, '22/7 is a rational number. Decimal expansions of rational numbers are either terminating or non-terminating recurring (repeating block of 6 digits: 3.142857...).', 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000003', 'The degree of the zero polynomial is:', '{"A":"0","B":"1","C":"Any natural number","D":"Not defined"}'::jsonb, 'D', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By standard algebraic definition, the degree of the zero polynomial p(x) = 0 is undefined.', 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000004', 'If (x - 1) is a factor of polynomial p(x) = kx² - 3x + k, what is the value of k?', '{"A":"3/2","B":"-3/2","C":"3","D":"-3"}'::jsonb, 'A', 'MCQ', 'Mathematics', 'Polynomials', 1, NULL, NULL, NULL, 'By Factor Theorem, p(1) = 0 -> k(1)² - 3(1) + k = 0 -> 2k - 3 = 0 -> k = 3/2.', 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000005', 'Point (-3, -5) lies in which quadrant of the Cartesian coordinate plane?', '{"A":"Quadrant I","B":"Quadrant II","C":"Quadrant III","D":"Quadrant IV"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Coordinate Geometry', 1, NULL, NULL, NULL, 'In Quadrant III, both the x-coordinate (abscissa) and y-coordinate (ordinate) are strictly negative.', 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000006', 'Express 0.2353535... (i.e. 0.235 with bar on 35) in the p/q form, where p and q are integers and q ≠ 0.', NULL, NULL, 'VSA', 'Mathematics', 'Number Systems', 2, 'Let x = 0.2353535... Multiplying by 10: 10x = 2.353535... (Eq 1). Multiplying by 1000: 1000x = 235.353535... (Eq 2). Subtracting Eq 1 from Eq 2: 990x = 233 -> x = 233 / 990.', '1 Mark for setting up equations with appropriate multipliers 10 and 1000; 1 Mark for subtraction and final simplified fraction 233/990', NULL, NULL, 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000007', 'Find the value of the polynomial p(y) = 2 + y + 2y² - y³ at: (i) y = 0, (ii) y = 2.', NULL, NULL, 'VSA', 'Mathematics', 'Polynomials', 2, '(i) p(0) = 2 + 0 + 2(0)² - (0)³ = 2. (ii) p(2) = 2 + 2 + 2(2)² - (2)³ = 4 + 8 - 8 = 4.', '1 Mark for calculating p(0) = 2; 1 Mark for calculating p(2) = 4', NULL, NULL, 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000008', 'Rationalise the denominator of: 1 / (7 + 3√2).', NULL, NULL, 'SA', 'Mathematics', 'Number Systems', 3, 'Multiplying numerator and denominator by conjugate (7 - 3√2): [1 * (7 - 3√2)] / [(7 + 3√2)(7 - 3√2)] = (7 - 3√2) / [7² - (3√2)²] = (7 - 3√2) / [49 - (9 * 2)] = (7 - 3√2) / (49 - 18) = (7 - 3√2) / 31.', '1 Mark for identifying conjugate; 1 Mark for denominator difference of squares (49 - 18); 1 Mark for final rationalized fraction', NULL, NULL, 'MEDIUM', true),
        ('9002001a-0000-4000-8000-000000000009', 'Factorise completely using the identity: 27x³ + y³ + z³ - 9xyz.', NULL, NULL, 'SA', 'Mathematics', 'Polynomials', 3, 'Rewrite as: (3x)³ + y³ + z³ - 3(3x)(y)(z). Using identity a³ + b³ + c³ - 3abc = (a + b + c)(a² + b² + c² - ab - bc - ca) where a = 3x, b = y, c = z: = (3x + y + z)[(3x)² + y² + z² - (3x)(y) - y(z) - z(3x)] = (3x + y + z)(9x² + y² + z² - 3xy - yz - 3zx).', '1 Mark for recognizing cubic identity; 1 Mark for substitution of terms; 1 Mark for expanded second polynomial factor', NULL, NULL, 'MEDIUM', true),
        ('9002001a-0000-4000-8000-00000000000a', 'A dome of a building is in the form of a hemisphere. From inside, it was whitewashed at the cost of ₹ 498.96. If the cost of whitewashing is ₹ 2.00 per square meter, find: (i) the inside surface area of the dome, (ii) the volume of the air inside the dome. (Use π = 22/7)', NULL, NULL, 'LA', 'Mathematics', 'Surface Areas and Volumes', 5, '(i) Cost = Rate * Area -> Inside surface area = Total Cost / Rate = 498.96 / 2 = 249.48 m². (ii) For hemisphere, inside CSA = 2πr² = 249.48. 2 * (22/7) * r² = 249.48 -> r² = (249.48 * 7) / 44 = 1746.36 / 44 = 39.69 -> r = √39.69 = 6.3 meters. Volume of air inside dome = (2/3)πr³ = (2/3) * (22/7) * (6.3)³ = (2/3) * (22/7) * 250.047 = (44/21) * 250.047 = 523.908 m³.', '2 Marks for finding inside surface area 249.48 m²; 1.5 Marks for calculating radius r = 6.3 m; 1.5 Marks for calculating volume 523.908 m³', NULL, NULL, 'MEDIUM', true)
