        ('9002002b-0000-4000-8000-000000000005', 'Point (-3, -5) lies in which quadrant of the Cartesian coordinate plane?', '{"A":"Quadrant I","B":"Quadrant II","C":"Quadrant III","D":"Quadrant IV"}'::jsonb, 'C', 'MCQ', 'Mathematics', 'Coordinate Geometry', 1, NULL, NULL, NULL, 'In Quadrant III, both the x-coordinate (abscissa) and y-coordinate (ordinate) are strictly negative.', 'MEDIUM', true),
        ('9002002b-0000-4000-8000-000000000006', 'Express 0.2353535... (i.e. 0.235 with bar on 35) in the p/q form, where p and q are integers and q ≠ 0.', NULL, NULL, 'VSA', 'Mathematics', 'Number Systems', 2, 'Let x = 0.2353535... Multiplying by 10: 10x = 2.353535... (Eq 1). Multiplying by 1000: 1000x = 235.353535... (Eq 2). Subtracting Eq 1 from Eq 2: 990x = 233 -> x = 233 / 990.', '1 Mark for setting up equations with appropriate multipliers 10 and 1000; 1 Mark for subtraction and final simplified fraction 233/990', NULL, NULL, 'MEDIUM', true),
        ('9002002b-0000-4000-8000-000000000007', 'Find the value of the polynomial p(y) = 2 + y + 2y² - y³ at: (i) y = 0, (ii) y = 2.', NULL, NULL, 'VSA', 'Mathematics', 'Polynomials', 2, '(i) p(0) = 2 + 0 + 2(0)² - (0)³ = 2. (ii) p(2) = 2 + 2 + 2(2)² - (2)³ = 4 + 8 - 8 = 4.', '1 Mark for calculating p(0) = 2; 1 Mark for calculating p(2) = 4', NULL, NULL, 'MEDIUM', true),
