        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('9002002e-0000-4000-8000-000000000001', 'Answer the following using Heron''s formula: (i) Find the semi-perimeter ''s'' of the triangular roof. (ii) Calculate the total surface area of the triangular roof. (iii) Calculate the total cost incurred in coating the entire roof.', NULL, NULL, 'CASE', 'Mathematics', 'Heron''s Formula', 4, '(i) s = (50 + 78 + 112) / 2 = 240 / 2 = 120 m. (ii) (s - a) = 120 - 50 = 70; (s - b) = 120 - 78 = 42; (s - c) = 120 - 112 = 8. Area = √[120 * 70 * 42 * 8] = √[(10 * 12) * (10 * 7) * (6 * 7) * 8] = √[10² * 7² * (12 * 48)] = √[10² * 7² * 576] = 10 * 7 * 24 = 1,680 m². (iii) Total cost = Area * Rate = 1680 * 40 = ₹ 67,200.', '1 Mark for semi-perimeter 120 m; 2 Marks for Heron area computation 1,680 m²; 1 Mark for total cost ₹ 67,200', 'To promote green energy, a school designs a triangular solar panel installation on its auditorium roof. The three sides of the triangular roof measure 50 m, 78 m, and 112 m. The school management plans to coat the roof with reflective solar sealant costing ₹ 40 per square meter before installing the panels.', NULL, 'MEDIUM', true),
        ('9002002e-0000-4000-8000-000000000002', 'Based on the Cartesian layout, answer: (i) In which quadrant does Hurdle A lie, and what is its perpendicular distance from the x-axis? (ii) What geometric shape is formed by joining the points A, B, C, and D in order? (iii) Find the perimeter of the figure ABCD.', NULL, NULL, 'CASE', 'Mathematics', 'Coordinate Geometry', 4, '(i) Hurdle A(4, 3) lies in Quadrant I. Its perpendicular distance from the x-axis is equal to the absolute ordinate |y| = 3 units. (ii) AB = 3 - (-3) = 6 units (vertical). BC = 4 - (-4) = 8 units (horizontal). CD = 6 units. DA = 8 units. All interior angles are 90°. Hence, ABCD forms a Rectangle. (iii) Perimeter = 2 * (length + breadth) = 2 * (8 + 6) = 2 * 14 = 28 units.', '1 Mark for Quadrant I and distance 3; 1.5 Marks for proving Rectangle; 1.5 Marks for calculating perimeter 28 units', 'Students of Class 9 organized a sports day race. The track is marked on a Cartesian grid where the starting point is at origin O(0, 0). Hurdle A is placed at point (4, 3), water booth B is at (4, -3), medical station C is at (-4, -3), and finish flag D is at (-4, 3).', NULL, 'MEDIUM', true),
        ('9002002e-0000-4000-8000-000000000003', 'Answer the following: (i) Calculate the slant height ''l'' of the conical tent. (ii) Find the area of canvas required to erect the tent (excluding the floor). (iii) Find the total cost of canvas fabric required.', NULL, NULL, 'CASE', 'Mathematics', 'Surface Areas and Volumes', 4, '(i) Slant height l = √(r² + h²) = √(7² + 24²) = √(49 + 576) = √625 = 25 meters. (ii) Canvas required = Curved Surface Area = πrl = (22/7) * 7 * 25 = 22 * 25 = 550 m². (iii) Total cost = Area * Rate = 550 * 70 = ₹ 38,500.', '1 Mark for slant height l = 25 m; 2 Marks for curved surface area 550 m²; 1 Mark for total cost ₹ 38,500', 'A residential welfare society constructed a conical canvas tent to serve as a community health camp. The radius of the base of the conical tent is 7 m, and its vertical height is 24 m. The canvas fabric used costs ₹ 70 per square meter.', NULL, 'MEDIUM', true),
        ('9002002e-0000-4000-8000-000000000004', 'Answer the following using Heron''s formula: (i) Find the semi-perimeter ''s'' of the triangular roof. (ii) Calculate the total surface area of the triangular roof. (iii) Calculate the total cost incurred in coating the entire roof.', NULL, NULL, 'CASE', 'Mathematics', 'Heron''s Formula', 4, '(i) s = (50 + 78 + 112) / 2 = 240 / 2 = 120 m. (ii) (s - a) = 120 - 50 = 70; (s - b) = 120 - 78 = 42; (s - c) = 120 - 112 = 8. Area = √[120 * 70 * 42 * 8] = √[(10 * 12) * (10 * 7) * (6 * 7) * 8] = √[10² * 7² * (12 * 48)] = √[10² * 7² * 576] = 10 * 7 * 24 = 1,680 m². (iii) Total cost = Area * Rate = 1680 * 40 = ₹ 67,200.', '1 Mark for semi-perimeter 120 m; 2 Marks for Heron area computation 1,680 m²; 1 Mark for total cost ₹ 67,200', 'To promote green energy, a school designs a triangular solar panel installation on its auditorium roof. The three sides of the triangular roof measure 50 m, 78 m, and 112 m. The school management plans to coat the roof with reflective solar sealant costing ₹ 40 per square meter before installing the panels.', NULL, 'MEDIUM', true),
        ('9002002e-0000-4000-8000-000000000005', 'Based on the Cartesian layout, answer: (i) In which quadrant does Hurdle A lie, and what is its perpendicular distance from the x-axis? (ii) What geometric shape is formed by joining the points A, B, C, and D in order? (iii) Find the perimeter of the figure ABCD.', NULL, NULL, 'CASE', 'Mathematics', 'Coordinate Geometry', 4, '(i) Hurdle A(4, 3) lies in Quadrant I. Its perpendicular distance from the x-axis is equal to the absolute ordinate |y| = 3 units. (ii) AB = 3 - (-3) = 6 units (vertical). BC = 4 - (-4) = 8 units (horizontal). CD = 6 units. DA = 8 units. All interior angles are 90°. Hence, ABCD forms a Rectangle. (iii) Perimeter = 2 * (length + breadth) = 2 * (8 + 6) = 2 * 14 = 28 units.', '1 Mark for Quadrant I and distance 3; 1.5 Marks for proving Rectangle; 1.5 Marks for calculating perimeter 28 units', 'Students of Class 9 organized a sports day race. The track is marked on a Cartesian grid where the starting point is at origin O(0, 0). Hurdle A is placed at point (4, 3), water booth B is at (4, -3), medical station C is at (-4, -3), and finish flag D is at (-4, 3).', NULL, 'MEDIUM', true)
